const manifest = $json.manifest || $json;
const hasAlerts = (manifest.n_alerts ?? 0) > 0 || (manifest.portfolio_alerts_count ?? 0) > 0;
return [{
  json: {
    status: hasAlerts ? "🚨 Alarm Bahaya Berbunyi" : "🛡️ Pasar Kondusif",
    run_id: manifest.run_id,
    scanned: manifest.n_gainers_scanned,
    alerts_count: manifest.n_alerts,
    portfolio_scanned: manifest.portfolio_stocks_scanned ?? 0,
    portfolio_alerts_count: manifest.portfolio_alerts_count ?? 0,
    portfolio_alerts: manifest.portfolio_alerts ?? {},
    errors_count: manifest.n_errors,
    alerts: manifest.alerts,
    started_at: manifest.started_at,
    finished_at: manifest.finished_at
  }
}];

const manifest = $json.manifest || $json;
const hasCandidates = (manifest.n_candidates ?? 0) > 0;
return [{
  json: {
    status: hasCandidates ? "🌅 Briefing Pagi Terkirim" : "✅ Tidak Ada Kandidat",
    run_id: manifest.run_id,
    candidates_count: manifest.n_candidates ?? 0,
    universe_scanned: manifest.n_universe_scanned ?? 0,
    candidates: manifest.candidates || [],
    errors_count: manifest.n_errors ?? 0,
    errors: manifest.errors || [],
    started_at: manifest.started_at,
    finished_at: manifest.finished_at
  }
}];

const res = $json;
return [{
  json: {
    status: (res.total_users ?? 0) > 0 ? "🛡️ Portofolio Terdaftar & Diawasi" : "📭 Belum Ada Aset Didaftarkan",
    total_warga: res.total_users ?? 0,
    total_saham_diawasi: res.unique_stocks_count ?? 0,
    daftar_saham: res.stocks ?? [],
    panduan: "Warga mendaftarkan saham via bot Telegram dengan perintah: /aset BBRI, BBCA, TLKM"
  }
}];
